// This is a simple interface which specifies echo.Route addition functions which
// are present on both echo.Echo and echo.Group, since we want to allow using
// either of them for path registration
type EchoRouter interface {
	CONNECT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	DELETE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	GET(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	HEAD(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	OPTIONS(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PATCH(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	POST(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PUT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	TRACE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
}

// RegisterHandlersOptions configures RegisterHandlersWithOptions.
type RegisterHandlersOptions struct {
	// BaseURL is prepended to every registered path so the API can be served
	// under a prefix.
	BaseURL string
	// OperationMiddlewares lets the caller attach per-operation middleware at
	// registration time. The map key is the OpenAPI `operationId` value as it
	// appears in the spec (the raw, un-normalized form). Operations that have
	// no entry are registered with no extra middleware. A nil map disables
	// per-operation middleware entirely.
	OperationMiddlewares map[string][]echo.MiddlewareFunc
}

// RegisterHandlers adds each server route to the EchoRouter.
func RegisterHandlers(router EchoRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{})
}

// RegisterHandlersWithBaseURL registers handlers and prepends BaseURL to the
// paths so the API can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{BaseURL: baseURL})
}

// RegisterHandlersWithOptions registers handlers using the supplied options,
// including any per-operation middleware.
func RegisterHandlersWithOptions(router EchoRouter, si ServerInterface, options RegisterHandlersOptions) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.POST(options.BaseURL+"/login", wrapper.Login, options.OperationMiddlewares["login"]...)
	router.POST(options.BaseURL+"/logout", wrapper.Logout, options.OperationMiddlewares["logout"]...)
	router.GET(options.BaseURL+"/me", wrapper.Me, options.OperationMiddlewares["me"]...)
	router.GET(options.BaseURL+"/products", wrapper.ListProducts, options.OperationMiddlewares["listProducts"]...)
	router.GET(options.BaseURL+"/products/recommendation", wrapper.RecommendProducts, options.OperationMiddlewares["recommendProducts"]...)
	router.GET(options.BaseURL+"/companies/:inn", wrapper.LookupCompany, options.OperationMiddlewares["lookupCompany"]...)
	router.GET(options.BaseURL+"/applications", wrapper.ListApplications, options.OperationMiddlewares["listApplications"]...)
	router.POST(options.BaseURL+"/applications", wrapper.CreateApplication, options.OperationMiddlewares["createApplication"]...)
	router.GET(options.BaseURL+"/applications/:id", wrapper.GetApplication, options.OperationMiddlewares["getApplication"]...)
	router.PATCH(options.BaseURL+"/applications/:id", wrapper.UpdateApplication, options.OperationMiddlewares["updateApplication"]...)
	router.POST(options.BaseURL+"/applications/:id/submit", wrapper.SubmitApplication, options.OperationMiddlewares["submitApplication"]...)
	router.POST(options.BaseURL+"/applications/:id/cancel", wrapper.CancelApplication, options.OperationMiddlewares["cancelApplication"]...)
	router.POST(options.BaseURL+"/applications/:id/provide-info", wrapper.ProvideInfo, options.OperationMiddlewares["provideInfo"]...)
	router.POST(options.BaseURL+"/applications/:id/accept", wrapper.AcceptOffer, options.OperationMiddlewares["acceptOffer"]...)
	router.POST(options.BaseURL+"/applications/:id/signing-code", wrapper.RequestSigningCode, options.OperationMiddlewares["requestSigningCode"]...)
	router.POST(options.BaseURL+"/applications/:id/sign", wrapper.SignApplication, options.OperationMiddlewares["signApplication"]...)
	router.GET(options.BaseURL+"/applications/:id/history", wrapper.ListApplicationEvents, options.OperationMiddlewares["listApplicationEvents"]...)
	router.POST(options.BaseURL+"/applications/:id/documents", wrapper.UploadDocument, options.OperationMiddlewares["uploadDocument"]...)
	router.GET(options.BaseURL+"/documents/:id", wrapper.GetDocument, options.OperationMiddlewares["getDocument"]...)
	router.GET(options.BaseURL+"/documents/:id/file", wrapper.DownloadDocument, options.OperationMiddlewares["downloadDocument"]...)
	router.POST(options.BaseURL+"/documents/:id/confirm", wrapper.ConfirmDocument, options.OperationMiddlewares["confirmDocument"]...)
	router.POST(options.BaseURL+"/applications/:id/decision", wrapper.DecideApplication, options.OperationMiddlewares["decideApplication"]...)
	router.POST(options.BaseURL+"/applications/:id/request-info", wrapper.RequestInfo, options.OperationMiddlewares["requestInfo"]...)
	router.POST(options.BaseURL+"/applications/:id/retry-checks", wrapper.RetryChecks, options.OperationMiddlewares["retryChecks"]...)
	router.GET(options.BaseURL+"/feed", wrapper.ListFeed, options.OperationMiddlewares["listFeed"]...)
	router.GET(options.BaseURL+"/health", wrapper.Health, options.OperationMiddlewares["health"]...)

}

